    got = yield "yield-%d" % tag
    print("resume", tag, got)

keep = [g(i) for i in range(6)]
for k in keep:
    print(next(k))

# Churn thousands of short generators while the six above stay suspended:
# their slots must survive, and freed slots must be reused without corruption.
for i in range(5000):
    gen = g(1000 + i)
    assert next(gen) == "yield-%d" % (1000 + i)
    gen.close()

for i, k in enumerate(keep):
    try:
        k.send("s%d" % i)
    except StopIteration:
        pass
print("done")
