def count_up(start):
    n = start
    while True:
        yield n
        n += 1

def take(it, k):
    out = []
    for x in it:
        if len(out) == k:
            break
        out.append(x)
    return out

def inner():
    x = yield 1
    print("inner got", x)
    yield 2
    return "done-inner"

def outer():
    r = yield from inner()
    print("outer saw", r)
    yield from [10, 20]
    yield from range(3)

def averager():
    total = 0
    count = 0
    avg = None
    while True:
        v = yield avg
        total += v
        count += 1
        avg = total / count

def walk(tree):
    if tree is None:
        return
    left, val, right = tree
    yield from walk(left)
    yield val
    yield from walk(right)

