import itertools

def count_up(start):
    n = start
    while True:
        yield n
        n += 1

def take(it, k):
    out = []
    for x in it:
        if len(out) == k:
            break
        out.append(x)
    return out

def inner():
    x = yield 1
    print("inner got", x)
    yield 2
    return "done-inner"

def outer():
    r = yield from inner()
    print("outer saw", r)
    yield from [10, 20]
    yield from range(3)

def averager():
    total = 0
    count = 0
    avg = None
    while True:
        v = yield avg
        total += v
        count += 1
        avg = total / count

def walk(tree):
    if tree is None:
        return
    left, val, right = tree
    yield from walk(left)
    yield val
    yield from walk(right)

class Board:
    def __init__(self, n):
        self.n = n
    def cells(self):
        for r in range(self.n):
            for c in range(self.n):
                yield (r, c)
    def __iter__(self):
        yield from self.cells()

def failing():
    yield 1
    raise ValueError("boom")

def make_counter(step):
    def gen(k):
        for i in range(k):
            yield i * step
    return gen

def chatty():
    print("start")
    yield "a"
    print("middle")
    yield "b"
    print("end")

